const p = msg.payload;

const required = [
    "eventId",
    "farmId",
    "shedId",
    "deviceId",
    "sensorType",
    "value",
    "unit",
    "recordedAt",
    "sequenceNumber"
];

const missing = required.filter(k =>
    p == null ||
    p[k] === undefined ||
    p[k] === null ||
    p[k] === ""
);

if (missing.length > 0) {
    msg.validationError = "Missing fields: " + missing.join(", ");
    return [null, msg];
}

const allowedSensors = [
    "temperature",
    "humidity",
    "ammonia",
    "feedWeight",
    "feedLevel",
    "waterLevel",
    "heartbeat"
];

if (!allowedSensors.includes(p.sensorType)) {
    msg.validationError = "Unknown sensor type: " + p.sensorType;
    return [null, msg];
}

if (
    p.sensorType !== "heartbeat" &&
    (typeof p.value !== "number" || !Number.isFinite(p.value))
) {
    msg.validationError = "Sensor value must be numeric";
    return [null, msg];
}

if (!Number.isInteger(p.sequenceNumber) || p.sequenceNumber < 1) {
    msg.validationError = "Invalid sequence number";
    return [null, msg];
}

if (Number.isNaN(Date.parse(p.recordedAt))) {
    msg.validationError = "Invalid recordedAt timestamp";
    return [null, msg];
}

msg.validation = "valid";
msg.validatedAt = new Date().toISOString();
return [msg, null];

const p = msg.payload;
const key = `${p.farmId}/${p.shedId}/${p.sensorType}`;

let counters = flow.get("faultCounters") || {};
let count = counters[key] || 0;

let unsafe = false;
let severity = "warning";
let rule = "";
let actions = [];

// ----------------------------
// Determine unsafe conditions
// ----------------------------

if (p.sensorType === "temperature" && p.value > 32) {
    unsafe = true;
    rule = "HIGH_TEMPERATURE";
    actions = [
        { actuator: "fan", state: "ON" },
        { actuator: "cooling", state: "ON" }
    ];
}
else if (p.sensorType === "humidity" && p.value > 70) {
    unsafe = true;
    rule = "HIGH_HUMIDITY";
    actions = [
        { actuator: "fan", state: "ON" }
    ];
}
else if (p.sensorType === "ammonia" && p.value > 20) {
    unsafe = true;
    severity = "critical";
    rule = "HIGH_AMMONIA";
    actions = [
        { actuator: "fan", state: "ON" }
    ];
}
else if (p.sensorType === "feedLevel" && p.value < 15) {
    unsafe = true;
    rule = "LOW_FEED";
    actions = [
        { actuator: "feeder", state: "ON" }
    ];
}
else if (p.sensorType === "waterLevel" && p.value < 15) {
    unsafe = true;
    rule = "LOW_WATER";
    actions = [
        { actuator: "pump", state: "ON" }
    ];
}

// ----------------------------
// Safe reading resets counter
// ----------------------------

if (!unsafe) {
    counters[key] = 0;
    flow.set("faultCounters", counters);
    return [null, null];
}

// ----------------------------
// Count consecutive faults
// ----------------------------

count += 1;
counters[key] = count;
flow.set("faultCounters", counters);

// First unsafe reading: wait for confirmation
if (count < 2) {
    return [null, null];
}

// Already triggered for this continuous fault.
// Do not send the same alert again.
if (count > 2) {
    return [null, null];
}

// ----------------------------
// Trigger exactly once at count 2
// ----------------------------

const createdAt = new Date().toISOString();

const alert = {
    alertId: `alert-${Date.now()}-${Math.random().toString(16).slice(2)}`,
    farmId: p.farmId,
    shedId: p.shedId,
    sensorType: p.sensorType,
    value: p.value,
    unit: p.unit,
    rule,
    severity,
    message: `${rule} detected in ${p.shedId}`,
    createdAt
};

const command = {
    farmId: p.farmId,
    shedId: p.shedId,
    reason: rule,
    actions,
    createdAt
};

return [
    {
        topic: `poultryguard/${p.farmId}/${p.shedId}/alerts`,
        payload: alert
    },
    {
        topic: `poultryguard/${p.farmId}/${p.shedId}/commands`,
        payload: command
    }
];
